<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require dirname(__DIR__).'/config/config.php';require dirname(__DIR__).'/public_html/lib/school_sms.php';
$db=db();queue_contract_expiry_sms($db);$processed=0;$limit=50;
while($processed<$limit){
 $db->beginTransaction();$q=$db->query("SELECT * FROM school_sms_outbox WHERE (status='queued' AND (next_attempt_at IS NULL OR next_attempt_at<=CURRENT_TIMESTAMP)) OR (status='sending' AND updated_at<DATE_SUB(CURRENT_TIMESTAMP,INTERVAL 15 MINUTE)) OR (status='accepted' AND provider_message_id IS NOT NULL AND (delivery_checked_at IS NULL OR delivery_checked_at<DATE_SUB(CURRENT_TIMESTAMP,INTERVAL 15 MINUTE)) AND (delivery_status IS NULL OR LOWER(delivery_status) IN ('pending','queued','sent','submitted','accepted'))) ORDER BY id LIMIT 1 FOR UPDATE");$row=$q->fetch();if(!$row){$db->commit();break;}$isCheck=(string)$row['provider_message_id']!=='';$db->prepare("UPDATE school_sms_outbox SET status='sending' WHERE id=?")->execute([$row['id']]);$db->commit();$processed++;
 if($isCheck){$check=check_director_sms_delivery((string)$row['provider_message_id']);if(!empty($check['ok'])){$state=strtolower((string)$check['delivery_status']);$terminal=in_array($state,['delivered','success','successful'],true)?'delivered':(in_array($state,['undelivered','failed','rejected','expired','submission_failed'],true)?'undelivered':'accepted');$db->prepare('UPDATE school_sms_outbox SET status=?,delivery_status=?,delivery_checked_at=CURRENT_TIMESTAMP,last_error=NULL WHERE id=?')->execute([$terminal,$state,$row['id']]);}else{$db->prepare("UPDATE school_sms_outbox SET status='accepted',delivery_checked_at=CURRENT_TIMESTAMP,last_error=? WHERE id=?")->execute([substr((string)($check['diagnostic']??'Delivery status is unavailable.'),0,1000),$row['id']]);}continue;}
 if($row['event_type']==='attendance_alert'){$check=$db->prepare("SELECT 1 FROM pupil_attendance WHERE id=? AND school_id=? AND pupil_id=? AND attendance_status IN ('absent','late')");$check->execute([$row['source_id'],$row['school_id'],$row['pupil_id']]);if(!$check->fetchColumn()){$db->prepare("UPDATE school_sms_outbox SET status='cancelled',last_error='Attendance status was corrected before delivery.' WHERE id=?")->execute([$row['id']]);continue;}}
 if($row['event_type']==='contract_expiry'){$check=$db->prepare("SELECT 1 FROM employee_contracts c JOIN school_memberships m ON m.school_id=c.school_id AND m.user_id=c.user_id JOIN users u ON u.id=c.user_id WHERE c.id=? AND c.school_id=? AND c.user_id=? AND c.status='active' AND c.end_date BETWEEN CURRENT_DATE AND DATE_ADD(CURRENT_DATE,INTERVAL 30 DAY) AND u.status='active' AND u.role NOT IN ('system_admin','sub_admin','admin','parent','pupil')");$check->execute([$row['source_id'],$row['school_id'],$row['recipient_user_id']]);if(!$check->fetchColumn()){$db->prepare("UPDATE school_sms_outbox SET status='cancelled',last_error='The staff contract is no longer active or within the notification period.' WHERE id=?")->execute([$row['id']]);continue;}}
 if($row['event_type']==='fee_reminder'){$check=$db->prepare("SELECT 1 FROM school_fee_ledger l JOIN pupils p ON p.id=l.pupil_id AND p.school_id=l.school_id WHERE l.id=? AND l.school_id=? AND l.pupil_id=? AND p.status='active'");$check->execute([$row['source_id'],$row['school_id'],$row['pupil_id']]);$sourceValid=(bool)$check->fetchColumn();$balance=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type IN ('charge','payment_reversal','discount_reversal') THEN amount WHEN entry_type IN ('payment','charge_reversal','discount') THEN -amount ELSE 0 END),0) FROM school_fee_ledger WHERE school_id=? AND pupil_id=?");$balance->execute([$row['school_id'],$row['pupil_id']]);if(!$sourceValid||(float)$balance->fetchColumn()<=0){$db->prepare("UPDATE school_sms_outbox SET status='cancelled',last_error='The pupil is inactive or no outstanding fee balance remains.' WHERE id=?")->execute([$row['id']]);continue;}}
 if($row['event_type']==='exam_publication'){$check=$db->prepare("SELECT 1 FROM school_exams e JOIN school_classes c ON c.id=e.class_id AND c.school_id=e.school_id JOIN school_class_subjects s ON s.id=e.subject_id AND s.class_id=c.id JOIN pupil_results r ON r.school_id=e.school_id AND r.exam_name=e.name AND r.academic_year=e.academic_year AND r.class_level=c.name AND r.subject=s.name JOIN pupils p ON p.id=r.pupil_id AND p.school_id=r.school_id WHERE e.id=? AND e.school_id=? AND e.status='results_published' AND p.id=? AND p.status='active'");$check->execute([$row['source_id'],$row['school_id'],$row['pupil_id']]);if(!$check->fetchColumn()){$db->prepare("UPDATE school_sms_outbox SET status='cancelled',last_error='Published result is no longer available.' WHERE id=?")->execute([$row['id']]);continue;}}
 if($row['event_type']==='school_announcement'){$recipient=$db->prepare("SELECT u.phone FROM users u JOIN pupil_guardians g ON g.guardian_user_id=u.id AND g.school_id=? JOIN school_announcements a ON a.id=? AND a.school_id=g.school_id WHERE u.id=? AND u.role='parent' AND u.status='active' AND g.receives_notifications=1 AND u.phone IS NOT NULL AND TRIM(u.phone)<>'' AND a.status='published' AND a.audience IN ('all','parents') AND (a.expires_at IS NULL OR a.expires_at>=CURRENT_DATE) LIMIT 1");$recipient->execute([$row['school_id'],$row['source_id'],$row['recipient_user_id']]);}
 elseif($row['event_type']==='contract_expiry'){$recipient=$db->prepare("SELECT u.phone FROM users u JOIN school_memberships m ON m.user_id=u.id AND m.school_id=? JOIN employee_contracts c ON c.user_id=u.id AND c.school_id=m.school_id WHERE c.id=? AND u.id=? AND c.status='active' AND c.end_date BETWEEN CURRENT_DATE AND DATE_ADD(CURRENT_DATE,INTERVAL 30 DAY) AND u.status='active' AND u.role NOT IN ('system_admin','sub_admin','admin','parent','pupil') AND u.phone IS NOT NULL AND TRIM(u.phone)<>'' LIMIT 1");$recipient->execute([$row['school_id'],$row['source_id'],$row['recipient_user_id']]);}
 else{$recipient=$db->prepare("SELECT u.phone FROM users u JOIN pupil_guardians g ON g.guardian_user_id=u.id AND g.school_id=? AND g.pupil_id=? WHERE u.id=? AND u.role='parent' AND u.status='active' AND g.receives_notifications=1 AND u.phone IS NOT NULL AND TRIM(u.phone)<>''");$recipient->execute([$row['school_id'],$row['pupil_id'],$row['recipient_user_id']]);}
 $phone=$recipient->fetchColumn();if($phone===false){$db->prepare("UPDATE school_sms_outbox SET status='cancelled',last_error='Guardian link, notification preference, account, event state, or phone is no longer valid.' WHERE id=?")->execute([$row['id']]);continue;}
 $attempt=(int)$row['attempts']+1;$result=shule_sms_send_notification((string)$phone,(string)$row['message_body'],'shulelite-'.$row['id']);if($result['accepted']){$db->prepare("UPDATE school_sms_outbox SET status='accepted',attempts=?,recipient_phone=?,http_status=?,provider_message_id=?,last_error=NULL,next_attempt_at=NULL WHERE id=?")->execute([$attempt,$result['recipient']??$phone,$result['http_status'],$result['message_id'],$row['id']]);}else{$final=$attempt>=4;$minutes=[5,30,120][$attempt-1]??120;$db->prepare('UPDATE school_sms_outbox SET status=?,attempts=?,recipient_phone=?,http_status=?,last_error=?,next_attempt_at=CASE WHEN ?=1 THEN NULL ELSE DATE_ADD(CURRENT_TIMESTAMP,INTERVAL ? MINUTE) END WHERE id=?')->execute([$final?'failed':'queued',$attempt,(string)$phone,$result['http_status'],substr((string)$result['diagnostic'],0,1000),$final?1:0,$minutes,$row['id']]);}
}
echo json_encode(['processed'=>$processed],JSON_THROW_ON_ERROR).PHP_EOL;
